ROOT=Path(__file__).resolve().parent.parent
OUT=ROOT/'dist'
ORIGIN='https://drytally-site.pages.dev'
def head(title,desc,path):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{ORIGIN}{path}"><meta name="theme-color" content="#FBF9F4"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{ORIGIN}{path}"><meta property="og:image" content="{ORIGIN}/assets/logo.png"><link rel="icon" href="/assets/favicon.png" type="image/png"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="stylesheet" href="/styles.css"></head><body><a class="skip" href="#main">Skip to content</a><div class="wrap"><header class="nav"><a class="brand" href="/" aria-label="Drytally home"><img src="/assets/logo.png" width="46" height="46" alt="Drytally character politely refusing a glass of wine">Drytally</a><nav class="nav-links" aria-label="Main navigation"><a class="hide-mobile" href="/#inside">The app</a><a href="/contact/">Contact</a><span class="pill">Made for iPhone</span></nav></header>'''
def foot():
 return '''<footer class="footer"><div><strong>Drytally</strong> · A little clarity, every day.<br>© 2026 Huiru Gao</div><nav class="footer-links" aria-label="Footer"><a href="/terms/">Terms of Use</a><a href="/privacy/">Privacy Policy</a><a href="/contact/">Contact us</a></nav></footer></div></body></html>'''
def linkify(text):
 t=escape(text)
 for raw,url in [('erchen735@gmail.com','mailto:erchen735@gmail.com'),('reportaproblem.apple.com','https://reportaproblem.apple.com/'),('apple.com/legal/privacy','https://www.apple.com/legal/privacy/'),('revenuecat.com/privacy','https://www.revenuecat.com/privacy/'),('cloudflare.com/privacypolicy','https://www.cloudflare.com/privacypolicy/')]:
  t=t.replace(raw,f'<a href="{url}">{raw}</a>')
 return t
for kind in ['terms','privacy']:
 d=json.loads((ROOT/'content'/f'{kind}.json').read_text());folder=OUT/kind;folder.mkdir(exist_ok=True)
 toc=''.join(f'<a href="#section-{i}">{escape(s["heading"])}</a>' for i,s in enumerate(d['sections'],1))
 body=''.join(f'<section id="section-{i}"><h2>{escape(s["heading"])}</h2>'+''.join('<p>'+linkify(p)+'</p>' for p in s['paragraphs'])+'</section>' for i,s in enumerate(d['sections'],1))
 html=head(d['title']+' · Drytally',d['summary'],'/'+kind+'/')+f'''<main id="main"><div class="legal-head"><p class="eyebrow"><span class="dot"></span>Drytally · Legal</p><h1>{escape(d['title'])}</h1><p class="summary">{escape(d['summary'])}</p><p class="legal-meta">Effective {d['effectiveDate']} · Version {d['version']}<br>Operator: {d['operator']} · <a href="mailto:{d['contactEmail']}">{d['contactEmail']}</a></p></div><div class="legal-layout"><aside class="toc" aria-label="Contents"><strong>On this page</strong>{toc}</aside><article class="legal-copy">{body}<div class="legal-end">Questions about this document?<br><a href="mailto:{d['contactEmail']}">Contact {d['operator']}</a> · <a href="/contact/">Support & privacy requests</a></div></article></div></main>'''+foot();(folder/'index.html').write_text(html)
# Illustrative calendar: interface language only, no claim about a user's results.
cells=''.join(f'<span class="{("dry" if i in [1,2,4,5,8,9,10,12,15,16,18] else "low" if i in [3,7,11,14,17] else "more" if i in [6,13] else "empty")}">{i}</span>' for i in range(1,29))
home=head('Drytally: Drinking Calendar','A calmer way to log drinks, see your patterns and make room for more alcohol-free days. An independent drinking diary for iPhone.','/')+f'''<main id="main"><section class="hero"><div><p class="eyebrow"><span class="dot"></span>A drinking diary. Without the lecture.</p><h1>Drink less.<br><span>Remember<br>more.</span></h1><p class="lede">A little honesty goes a long way. Log your drinks, see your days clearly, and find a pace that feels like yours.</p><div class="actions"><a class="btn" href="#inside">Meet Drytally <span aria-hidden="true">↗</span></a><a class="text-link" href="/privacy/">Your diary, your business</a></div><p class="availability">Coming to iPhone · iOS 17 and later</p></div><div class="hero-art" aria-label="Drytally app preview"><div class="green-plate"></div><div class="phone"><img src="/assets/app-home.png" width="1179" height="2556" alt="Drytally Today screen showing the drinking calendar and local drink totals"></div><div class="floating float-note">One day at a time.<div class="line"></div></div><div class="floating float-days"><span class="mini-check" aria-hidden="true">✓</span><span><strong>More room for dry days.</strong><small>A record. A fresh perspective.</small></span></div></div></section><div class="principles" aria-label="Product principles"><span><i aria-hidden="true">◌</i>No diary account needed</span><span><i aria-hidden="true">⌁</i>Made for your own pace</span><span><i aria-hidden="true">◇</i>Diary stored on your iPhone</span></div><section class="section" id="inside"><div class="section-heading"><h2>A clearer picture.<br>A gentler approach.</h2><p>No perfect streak required. Just a simple record that makes it easier to notice what is changing.</p></div><div class="feature-grid"><article class="feature"><div class="calendar-art" aria-label="Illustrative drinking calendar"><div class="calendar-top"><span>YOUR MONTH</span><span aria-hidden="true">↗</span></div><div class="cal-labels"><span>M</span><span>T</span><span>W</span><span>T</span><span>F</span><span>S</span><span>S</span></div><div class="cal-grid">{cells}</div><div class="legend"><span><i style="background:var(--sage)"></i>Alcohol-free</span><span><i style="background:var(--wheat)"></i>1–2 drinks</span><span>Illustration</span></div></div><h3>Your days, at a glance.</h3><p>A colour-coded calendar brings the big picture into focus. Log a day, adjust a count, and see your own pattern take shape.</p></article><div class="right-features"><article class="mini-feature"><div class="bars" aria-hidden="true"><i style="height:22px"></i><i style="height:37px"></i><i style="height:16px"></i><i style="height:29px"></i><i style="height:43px"></i><i style="height:25px"></i></div><h3>Notice the little shifts.</h3><p>Explore your month and year, alcohol-free days and estimated spending. Your own entries tell the story.</p></article><article class="mini-feature"><div class="journal-mark" aria-hidden="true">A day. A note. A little context.</div><h3>More than a number.</h3><p>Add personal notes and selected photos, or revisit your patterns with insights and exports. Notes, insights and exports are part of Pro.</p></article></div></div><p class="caption">App preview uses sample entries. Calendar artwork is illustrative. Your record and totals depend on what you log.</p></section><section class="section" style="padding-top:0"><div class="section-heading"><h2>Keep it simple.</h2><p>A quiet habit that fits into the day you already have.</p></div><div class="how"><article class="how-step"><span class="step-num">01 / RECORD</span><h3>Log what happened.</h3><p>Add drinks or record an alcohol-free day during your 24-hour preview or with unlocked access. Explicit zero and an unlogged day stay distinct.</p></article><article class="how-step"><span class="step-num">02 / NOTICE</span><h3>Look back with curiosity.</h3><p>See the calendar and your totals. An unlogged day stays unlogged; it is never automatically counted as a dry day.</p></article><article class="how-step"><span class="step-num">03 / CONTINUE</span><h3>Make space for tomorrow.</h3><p>Choose an optional local reminder or a home-screen widget. A little encouragement, on your terms.</p></article></div></section><section class="privacy-band" aria-labelledby="privacy-title"><div><p class="eyebrow">A personal diary should feel personal.</p><h2 id="privacy-title">Your diary stays<br>on your iPhone.</h2></div><div class="details"><p>No Drytally diary account. No public feed. Your entries, notes and selected photos stay in local app storage unless you choose to share them or use an optional Apple service.</p><p>Purchases, website visits and support email have separate data flows. We explain them plainly, too.</p><a href="/privacy/">Read the full Privacy Policy <span aria-hidden="true">↗</span></a></div></section><section class="section faq-layout"><div><p class="eyebrow">A few things to know</p><h2>Clear answers.<br>No fine-print maze.</h2><p>Something else on your mind?<br><a class="text-link" href="/contact/">We’re here to help ↗</a></p></div><div class="faq"><details><summary>Do I have to stop drinking completely?</summary><p>Drytally is a diary, not a prescribed programme. You can use it to understand your drinking, cut back or record alcohol-free days. Health decisions belong with you and a qualified professional.</p></details><details><summary>What is free, and what is Pro?</summary><p>Try the app for 24 continuous hours after first agreement acceptance. Afterwards, today’s existing content is read-only; logging, editing, history and other features require valid access. No automatic charge occurs when the preview ends. Weekly and Lifetime purchases are optional; Apple shows the actual price and terms.</p></details><details><summary>Does it sync my diary to the cloud?</summary><p>Your diary works locally. Optional iCloud history sync is off by default and requires valid access, a supported build and your Apple account. Changes take effect after restarting the app. Photos stay on this device; iCloud history is not a photo backup. The operator-hosted purchase backend does not receive diary entries.</p></details><details><summary>Do I need to connect Apple Health?</summary><p>No. Health writing is optional and controlled by your permission. You can keep a local diary without enabling it, and change access later in iOS settings.</p></details><details><summary>Is Drytally medical advice?</summary><p>No. It is a personal record-keeping tool, not a medical device, treatment programme or emergency service. It does not determine whether alcohol use is safe or promise a health outcome.</p></details><details><summary>How can I get support or make a privacy request?</summary><p>Visit <a href="/contact/">Contact us</a> or email <a href="mailto:erchen735@gmail.com">erchen735@gmail.com</a>. For privacy requests, use “Privacy request” as the subject. Please send only information relevant to your question.</p></details></div></section><section class="closing"><p>Try the app for 24 continuous hours. Afterwards, today’s saved content remains read-only. Unlock to keep logging, view history and use other features. No automatic charge when the preview ends.</p><div><img src="/assets/logo.png" width="90" height="90" alt="Drytally app icon"><h2>A little clarity, every day.</h2><p>Made for people who want an honest record and a little more room to choose. Coming to iPhone.</p></div><a class="btn secondary" href="/contact/">Get in touch <span aria-hidden="true">↗</span></a></section></main>'''+foot()
(OUT/'index.html').write_text(home)
contact=head('Contact us · Drytally','Support, privacy requests and legal enquiries for Drytally. Contact Huiru Gao at erchen735@gmail.com.','/contact/')+'''<main id="main"><div class="contact-head"><p class="eyebrow"><span class="dot"></span>Contact us</p><h1>A real person.<br>A clear place to ask.</h1><p>Questions about Drytally, a purchase or your privacy? Get in touch and tell us what you need.</p></div><div class="contact-grid contact-copy"><section class="contact-card"><h2>Support & general enquiries</h2><p>For app questions, purchase-access problems, feedback or a bug you’ve noticed.</p><a class="email" href="mailto:erchen735@gmail.com?subject=Drytally%20support">erchen735@gmail.com ↗</a><p>Include your app version, iOS version and a short description. Screenshots can help, but remove diary entries or other personal information that is not needed.</p><p class="small">Operator: Huiru Gao. This is email support, not a live chat or emergency service.</p></section><section class="contact-card"><h2>Privacy & legal requests</h2><p>Use the same email with the subject “Privacy request” or “Legal enquiry”. Tell us which interaction or information your request concerns.</p><p>We cannot retrieve a local diary that has never been sent to us. Your legal rights concerning information we actually hold do not depend on a Pro purchase.</p><p><a href="mailto:erchen735@gmail.com?subject=Drytally%20privacy%20request">Send a privacy request ↗</a></p><p><a href="/privacy/">Privacy Policy</a> · <a href="/terms/">Terms of Use</a></p></section></div><section class="closing"><div><h2>Before you send.</h2><p>Never include passwords, verification codes or payment-card details. Apple manages subscription cancellation and refund requests through your Apple Account.</p></div><a class="btn secondary" href="https://reportaproblem.apple.com/" rel="noopener">Apple purchase help ↗</a></section></main>'''+foot();(OUT/'contact').mkdir(exist_ok=True);(OUT/'contact/index.html').write_text(contact)
(OUT/'404.html').write_text(head('Page not found · Drytally','Return to Drytally.','/404.html')+'<main id="main" class="contact-head"><h1>This page took<br>a different turn.</h1><p>Let’s get you back to Drytally.</p><a class="btn" href="/">Back home ↗</a></main>'+foot())
